test('finds the largest of several', () => { assert.equal(largestNumber([3, 9, 2]), 9); });
test('works when all numbers are negative', () => { assert.equal(largestNumber([-5, -2, -9]), -2); });
test('single item', () => { assert.equal(largestNumber([7]), 7); });
test('largest at the start', () => { assert.equal(largestNumber([10, 1, 4]), 10); });
test('empty array gives null', () => { assert.equal(largestNumber([]), null); });

referenceSolution:
function largestNumber(numbers) {
  if (numbers.length === 0) {
    return null;
  }
  let largest = numbers[0];
  for (const n of numbers) {
    if (n > largest) {
      largest = n;
    }
  }
  return largest;
}

